export const iconTint: Record<string, string> = {
  php:"#777bb4",python:"#3776ab",javascript:"#f7df1e",typescript:"#3178c6",go:"#00add8",laravel:"#ff2d20",
  symfony:"#20242c",magento:"#f26322",wordpress:"#21759b",woocommerce:"#96588a",django:"#092e20",fastapi:"#009688",
  flask:"#20242c",reflex:"#5b4dff",streamlit:"#ff4b4b",dash:"#008de4",gradio:"#f97316",nextdotjs:"#20242c",
  nuxtdotjs:"#00dc82",svelte:"#ff3e00",astro:"#bc52ee",express:"#20242c",nestjs:"#e0234e",fastify:"#20242c",
  hono:"#e36002",adonisjs:"#5a45ff",nodedotjs:"#5fa04e",turborepo:"#ef4444",docker:"#2496ed",postgresql:"#4169e1",
  mariadb:"#003545",mysql:"#4479a1",sqlite:"#003b57",redis:"#ff4438",opensearch:"#005eb8",elasticsearch:"#005571",
  meilisearch:"#ff5caa",minio:"#c72e49",rabbitmq:"#ff6600",mongodb:"#47a248",nginx:"#009639",
  typesense:"#d52d6e",varnish:"#f4a261",apache:"#d22128"};

export function Icon({ r, size = 21 }: { r: any; size?: number }) {
  const slug = iconSlug(r)
  const s = size
  const box: CSSProperties = {
    width: s, height: s, borderRadius: 5, display: 'inline-flex',
    alignItems: 'center', justifyContent: 'center',
    background: (slug && iconTint[slug]) || '#8b93a1', flex: 'none', verticalAlign: 'middle',
  }
  if (!slug) return null
  const p = BRAND_SVG[slug]
  if (p) {
    const gs = Math.round(s * 0.66)
    return (
      <span className="ic" title={slug} style={box}>
        <svg width={gs} height={gs} viewBox="0 0 24 24" fill="#fff" aria-hidden="true"><path d={p} /></svg>
      </span>
    )
  }
  return (
    <span className="ic" title={slug} style={{ ...box, lineHeight: `${s}px`, textAlign: 'center', fontSize: Math.round(s * 0.55), fontWeight: 700, color: '#0f1218' }}>
      {slug[0].toUpperCase()}
    </span>
  )
}

// IconOrPi mirrors the original `iconImg(...) || '<span class="pi">'`: the brand
// icon when the slug resolves, else the neutral placeholder square.
export function IconOrPi({ r, size = 21 }: { r: any; size?: number }) {
  return iconSlug(r) ? <Icon r={r} size={size} /> : <span className="pi" />
}
